import {LOCAL_LIFT} from './local-lift-config.js';import {LEVELS,LANDING} from './architecture.js';
export const initialLocalLift=()=>({liftY:0,liftTarget:0,liftFrom:0,liftTime:0,liftActive:false,liftPassenger:false,liftState:'open',liftGate:0});
export function localLiftOwner(s,x,z,y,cabin){const dx=LOCAL_LIFT.offset.x,dz=LOCAL_LIFT.offset.z,lx=x-dx,lz=z-dz;if(lx>=cabin.x&&lx<=cabin.x+cabin.w&&lz>=cabin.z&&lz<=cabin.z+cabin.d&&Math.abs(y-s.localLift.liftY)<.01)return'local-lift';const floor=LOCAL_LIFT.levels.find(v=>Math.abs(v-y)<.01);if(floor===undefined)return null;const id='LF'+LEVELS.indexOf(floor);if(lx>=LANDING.x&&lx<=-.4&&lz>=2&&lz<=6)return id;if(lx>=-2.65&&lx<=-2.4&&lz>=2.4&&lz<=5.6)return id;return null;}
export function localLiftCollisionLines(s,cabin,fixedWalls){const out=[],dx=LOCAL_LIFT.offset.x,dz=LOCAL_LIFT.offset.z,add=(l,owner,y)=>out.push({a:[l.a[0]+dx,l.a[1]+dz],b:[l.b[0]+dx,l.b[1]+dz],owner,y}),c=s.localLift;
 for(const y of LOCAL_LIFT.levels){const owner='LF'+LEVELS.indexOf(y);for(const l of fixedWalls())add(l,owner,y);if(c.liftGate>.001||Math.abs(c.liftY-y)>.01)add({a:[-2.5,2.4],b:[-2.5,5.6]},owner,y);const p=s.livePorts.find(p=>p.key===owner+':E');for(const m of p?.masked??[{a:1,b:3}])add({a:[-.46,LANDING.z+m.a],b:[-.46,LANDING.z+m.b]},owner,y);}
 for(const l of [{a:[cabin.x+.06,cabin.z],b:[cabin.x+.06,cabin.z+cabin.d]},{a:[cabin.x,cabin.z+.06],b:[cabin.x+cabin.w,cabin.z+.06]},{a:[cabin.x,cabin.z+cabin.d-.06],b:[cabin.x+cabin.w,cabin.z+cabin.d-.06]},{a:[-2.71,2.05],b:[-2.71,2.4]},{a:[-2.71,5.6],b:[-2.71,5.95]}])add(l,'local-lift',c.liftY);if(c.liftGate>.001)add({a:[-2.71,2.4],b:[-2.71,5.6]},'local-lift',c.liftY);return out;
}
